    Write-Host "run-job inventory-row test passed"
}
finally {
    if (Test-Path $tempRoot) { Remove-Item -LiteralPath $tempRoot -Recurse -Force }
}
# Shared helpers for the KeystoneOS run ledger and job registry.
# Dot-source this file; it defines functions and does no work on its own.
#
# The ledger answers one question nothing else could answer: "did this job actually
# succeed today?" Before it existed, the scheduler's own history was the only record,
# and that records "the process exited", not "the work happened".

Set-StrictMode -Version Latest

function Get-KeystoneRoot {
    (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..")).Path
}

function Get-KeystoneDevRoot {
    # DEV is the parent of the KeystoneOS repo.
    (Resolve-Path -LiteralPath (Join-Path (Get-KeystoneRoot) "..")).Path
}

function Expand-JobToken {
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Value,
        [datetime]$Date = (Get-Date)
    )
    $out = $Value
    $out = $out.Replace("{REPO}", (Get-KeystoneRoot))
    $out = $out.Replace("{DEV}", (Get-KeystoneDevRoot))
    $out = $out.Replace("{USERPROFILE}", $HOME)
    $out = $out.Replace("{DATE}", $Date.ToString("yyyy-MM-dd"))
    $out
}

function Get-JobRegistry {
    param([string]$Path)
    if (-not $Path) { $Path = Join-Path (Get-KeystoneRoot) "data/jobs.json" }
    if (-not (Test-Path -LiteralPath $Path)) { throw "Job registry not found: $Path" }
    $raw = Get-Content -Raw -LiteralPath $Path
    ($raw | ConvertFrom-Json).jobs
}

function Get-JobDefinition {
    param(
        [Parameter(Mandatory)][string]$Id,
        [string]$RegistryPath
    )
    $job = Get-JobRegistry -Path $RegistryPath | Where-Object { $_.id -eq $Id }
    if (-not $job) { throw "Unknown job id '$Id'. Check data\jobs.json." }
    $job
}

function Get-LedgerPath {
    param([string]$Root)
    if (-not $Root) { $Root = Get-KeystoneRoot }
    Join-Path $Root "outputs/run-ledger.json"
}

